/*
 * Preloader — loads every shipped asset (ATG.ASSET_LIST, generated by
 * tools/asset-manifest.mjs with real byte sizes) behind the title's progress
 * bar. Start Mission stays hidden until every transfer has finished.
 *
 * - Title art and fonts go first; everything else smallest first, five at a
 *   time. Streamed byte counts drive the bar, Content-Length refines the
 *   listed size, and the bar never moves backwards.
 * - Images, sprite sheets, backgrounds and audio are fetched into local blob:
 *   URLs. What the title shows from the first frame (its art and the fonts) is
 *   tracked through the browser's own load instead, so nothing downloads twice.
 * - A failed, stalled (no bytes for STALL_MS) or aborted transfer counts as
 *   done and that asset simply keeps its file URL. On file:// (where fetch is
 *   blocked) nothing is fetched and Start appears straight away.
 *
 * API: ATG.asset(path) → blob: URL when there is one, else the path.
 *      ATG.assetReady(path) → Promise of that URL once the asset has loaded.
 *      ATG.assetOrig(url) → the file behind a blob: URL (one-time error fallback).
 *      ATG.preload.ready / .done / .progress / .stats
 * Static <img data-src> elements get their src from here as their file lands.
 */
(function (ATG) {
  'use strict';

  var CONCURRENCY = 5;
  var STALL_MS = 15000;
  var TYPES = { webp: 'image/webp', ogg: 'audio/ogg', mp3: 'audio/mpeg' };
  var TITLE_ART = ['assets/images/ui/logo_autocomplete_trap.webp'];   // plus the title background and cast (read below)
  var CSS_VARS = {                    // images the stylesheets use, exposed as custom properties
    'assets/images/ui/ui_robot_dialogue_frame.webp': '--img-robot-frame',
    'assets/images/characters/blip/spr_blip_states.webp': '--img-blip-states'
  };

  var blobs = {};                     // path -> blob: URL
  var origs = {};                     // blob: URL -> path
  var keep = [];                      // natively loaded title art, held so it stays cached
  var listeners = [];
  var shown = 0;
  var resolveReady;
  var P = ATG.preload = {
    done: false,
    progress: 0,
    stats: { files: 0, ok: 0, failed: 0, bytes: 0, order: [] },
    ready: new Promise(function (r) { resolveReady = r; }),
    onProgress: function (fn) { listeners.push(fn); fn(P.progress); }
  };

  var items = (ATG.ASSET_LIST || []).map(function (row) { return { path: row[0], expect: row[1], loaded: 0, finished: false, waiters: [] }; });
  var byPath = {};
  items.forEach(function (it) { byPath[it.path] = it; });
  P.stats.files = items.length;
  var total = items.reduce(function (t, it) { return t + it.expect; }, 0) || 1;

  ATG.asset = function (path) { return blobs[path] || path; };
  ATG.assetOrig = function (url) { return origs[url] || null; };
  ATG.assetReady = function (path) {
    var it = byPath[path];
    if (!it || it.finished || P.done) return Promise.resolve(ATG.asset(path));
    return new Promise(function (r) { it.waiters.push(r); });
  };

  /* One-time fallback: an image whose blob: URL fails reverts to its file. */
  document.addEventListener('error', function (e) {
    var el = e.target;
    if (!el || el.tagName !== 'IMG' || el.dataset.assetReverted) return;
    var orig = origs[el.getAttribute('src')];
    if (!orig) return;
    el.dataset.assetReverted = '1';
    el.src = orig;
  }, true);

  function report() {
    var got = 0;
    for (var i = 0; i < items.length; i++) got += items[i].finished ? items[i].expect : Math.min(items[i].loaded, items[i].expect);
    var k = items.length ? Math.min(1, got / total) : 1;
    if (k > P.progress) P.progress = k;     // monotonic
    if (P.done) P.progress = 1;
    if (painting) return;
    painting = true;
    (window.requestAnimationFrame || setTimeout)(function () {
      painting = false;
      if (P.progress === shown && !P.done) return;
      shown = P.progress;
      listeners.forEach(function (fn) { fn(shown); });
    });
  }
  var painting = false;

  /* Hand a finished asset (local or not) to everything waiting for it. */
  function deliver(it) {
    var url = ATG.asset(it.path);
    var imgs = document.querySelectorAll('img[data-src="' + it.path + '"]');
    for (var i = 0; i < imgs.length; i++) { imgs[i].src = url; imgs[i].removeAttribute('data-src'); }
    if (CSS_VARS[it.path] && blobs[it.path]) document.documentElement.style.setProperty(CSS_VARS[it.path], 'url("' + url + '")');
    it.waiters.splice(0).forEach(function (r) { r(url); });
  }

  function finisher(it) {
    var t0 = performance.now();
    return function finish(ok) {
      if (it.finished) return;
      it.finished = true;
      P.stats[ok ? 'ok' : 'failed'] += 1;
      P.stats.order.push({ path: it.path, ok: ok, start: Math.round(t0), end: Math.round(performance.now()) });
      deliver(it);
      report();
    };
  }

  /* Title art already on screen: count the browser's own load of it. */
  function loadNative(it) {
    var finish = finisher(it);
    return new Promise(function (resolve) {
      var done = function (ok) { clearTimeout(t); if (ok) { it.loaded = it.expect; P.stats.bytes += it.expect; } finish(ok); resolve(); };
      var t = setTimeout(function () { done(false); }, STALL_MS * 2);
      if (it.font) {
        document.fonts.load(it.font).then(function (f) { done(f.length > 0); }, function () { done(false); });
        return;
      }
      var im = new Image();
      im.onload = function () { done(true); };
      im.onerror = function () { done(false); };
      im.src = it.path;
      keep.push(im);
    });
  }

  function load(it) {
    if (it.native) return loadNative(it);
    var finish = finisher(it);
    var ctrl = window.AbortController ? new AbortController() : null;
    var stall;
    function arm() { clearTimeout(stall); stall = setTimeout(function () { if (ctrl) ctrl.abort(); }, STALL_MS); }
    arm();
    return fetch(it.path, ctrl ? { signal: ctrl.signal } : {}).then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      var len = Number(res.headers.get('content-length'));
      if (len > 0 && !res.headers.get('content-encoding') && len !== it.expect) { total += len - it.expect; it.expect = len; }
      var type = TYPES[it.path.split('.').pop()] || res.headers.get('content-type') || '';
      // blob() owns the body (it waits for the transfer to complete); a streamed
      // clone only counts bytes for the bar. Reading the body itself with a
      // reader lets Chrome cancel the finished request (reported as aborted).
      var probe = res.clone().body;
      var body = res.blob();
      if (probe && probe.getReader) {
        var reader = probe.getReader();
        var pump = function () {
          return reader.read().then(function (r) {
            if (r.done) return;
            arm();
            it.loaded += r.value.byteLength;
            P.stats.bytes += r.value.byteLength;
            report();
            return pump();
          });
        };
        pump().catch(function () { /* progress only */ });
      }
      return body.then(function (b) {
        if (!it.loaded) { it.loaded = b.size; P.stats.bytes += b.size; }
        return b.type === type ? b : new Blob([b], { type: type });
      });
    }).then(function (blob) {
      clearTimeout(stall);
      var url = URL.createObjectURL(blob);
      blobs[it.path] = url;
      origs[url] = it.path;
      finish(true);
    }, function (err) {
      clearTimeout(stall);
      console.warn('[preload] ' + it.path + ' not preloaded (' + (err && err.name === 'AbortError' ? 'stalled' : (err && err.message) || err) + '); it will load from the file.');
      finish(false);
    });
  }

  /* Point every data map (and anything already rendered) at the local copies. */
  function swap() {
    var D = ATG.DATA;
    function walk(obj) {
      Object.keys(obj).forEach(function (k) {
        var v = obj[k];
        if (typeof v === 'string') { if (blobs[v]) obj[k] = blobs[v]; }
        else if (v && typeof v === 'object') walk(v);
      });
    }
    if (D) {
      walk(D.KRISH_ASSETS); walk(D.BACKGROUNDS); walk(D.IMAGES); walk(D.AUDIO);
      Object.keys(D.SPRITES).forEach(function (k) { walk(D.SPRITES[k]); });
      Object.keys(D.LINES).forEach(function (k) { walk(D.LINES[k]); });
    }
    var imgs = document.querySelectorAll('img[src^="assets/"]');
    for (var i = 0; i < imgs.length; i++) {
      var src = imgs[i].getAttribute('src');
      if (blobs[src]) imgs[i].src = blobs[src];
    }
  }

  function complete() {
    if (P.done) return;
    items.forEach(function (it) { if (!it.finished) { it.finished = true; deliver(it); } });
    try { swap(); } catch (e) { console.warn('[preload] swap failed; assets load from their files.', e); }
    P.done = true;
    report();
    resolveReady();
  }

  /* What the title shows from the first frame loads natively, first. */
  function markNative() {
    var D = ATG.DATA || {};
    var first = TITLE_ART.concat(D.BACKGROUNDS ? [D.BACKGROUNDS.title] : []);
    var cast = document.querySelectorAll('.scene--title img[src^="assets/"]');
    for (var i = 0; i < cast.length; i++) first.push(cast[i].getAttribute('src'));
    first.forEach(function (p) { if (byPath[p]) byPath[p].native = true; });
    // Fonts: matched to their @font-face rule so document.fonts loads the very file CSS uses.
    try {
      Array.prototype.forEach.call(document.styleSheets, function (sheet) {
        Array.prototype.forEach.call(sheet.cssRules || [], function (rule) {
          if (rule.type !== 5) return; // CSSRule.FONT_FACE_RULE
          var m = /url\("?(?:\.\.\/)?(assets\/fonts\/[^")]+)"?\)/.exec(rule.style.getPropertyValue('src'));
          if (!m || !byPath[m[1]]) return;
          var w = String(rule.style.getPropertyValue('font-weight') || '400').split(' ')[0];
          byPath[m[1]].native = true;
          byPath[m[1]].font = w + ' 16px ' + rule.style.getPropertyValue('font-family');
        });
      });
    } catch (e) { /* unreadable stylesheet: fonts are fetched like any other file */ }
  }

  if (location.protocol === 'file:' || !window.fetch || !items.length) {
    complete();
  } else {
    markNative();
    var rank = function (it) { return it.native ? 0 : 1; };
    var queue = items.slice().sort(function (a, b) { return rank(a) - rank(b) || a.expect - b.expect; });
    var next = function () {
      var it = queue.shift();
      return it ? load(it).then(next) : null;
    };
    var workers = [];
    for (var w = 0; w < CONCURRENCY; w++) workers.push(Promise.resolve().then(next));
    Promise.all(workers).then(complete, complete);
  }

  /* Title UI: fill the bar, then trade it for the Start button. */
  function bindTitle() {
    var bar = document.getElementById('loader');
    var fill = document.getElementById('loaderFill');
    var pct = document.getElementById('loaderPct');
    var btn = document.getElementById('startBtn');
    if (!bar || !btn) return;
    P.onProgress(function (k) {
      var n = Math.floor(k * 100);
      fill.style.transform = 'scaleX(' + k.toFixed(4) + ')';
      pct.textContent = n + '%';
      bar.setAttribute('aria-valuenow', String(n));
    });
    P.ready.then(function () {
      bar.classList.add('is-done');
      setTimeout(function () {
        bar.hidden = true;
        btn.hidden = false;
        btn.classList.add('is-popping');
        btn.addEventListener('animationend', function () { btn.classList.remove('is-popping'); }, { once: true });
      }, location.protocol === 'file:' ? 0 : 320);
    });
  }
  bindTitle();
})(window.ATG = window.ATG || {});
